{"filename":"app.py","content":"import os
from flask import Flask, jsonify, send_from_directory, abort
from routes import bp
import models

app = Flask(__name__)

# Initialize the generated schema before serving any API request. The models
# and routes modules are required to share this database connection/schema.
if callable(getattr(models, "init_app", None)):
    models.init_app(app)
elif callable(getattr(models, "init_db", None)):
    with app.app_context():
        models.init_db()

@app.get("/")
def index():
    return send_from_directory(app.root_path, "index.html")

# Keep the generated UI root ahead of API routes, even if a model emits a duplicate.
app.register_blueprint(bp)

# ---------------------------------------------------------------------------
# Compatibility route: accept the OpenAPI‑style placeholder syntax "/workouts/:id"
# and forward the request to the correctly defined "<int:id>" endpoint.
# This ensures clients using the placeholder receive the expected response.
# ---------------------------------------------------------------------------
@app.get("/workouts/:<int:id>")
def get_workout_placeholder(id):
    # Locate the original endpoint that handles "/workouts/<int:id>".
    for rule in app.url_map.iter_rules():
        if rule.rule == "/workouts/<int:id>":
            view_func = app.view_functions.get(rule.endpoint)
            if view_func:
                return view_func(id)
    # If the original endpoint cannot be found, return a generic 404.
    abort(404)

@app.get("/style.css")
def stylesheet():
    return send_from_directory(app.root_path, "style.css")

@app.get("/script.js")
def javascript():
    return send_from_directory(app.root_path, "script.js")

@app.errorhandler(404)
def not_found(_error):
    return jsonify({"error": "Not found"}), 404

if __name__ == "__main__":
    port = int(os.environ.get("PORT", 5000))
    app.run(host="127.0.0.1", port=port, debug=False, use_reloader=False)"}
